/**
 * Source API — current retold stack.
 *
 * meadow-endpoints 4.x / orator 6 / fable 3, served by retold-data-service.
 *
 * The source store is engine-switchable so the clone is exercised across a
 * database boundary: SOURCE_ENGINE=postgres (default) or mssql.
 */
const libPath = require('path');

const libFable = require('fable');
const libRetoldDataService = require('retold-data-service');

const _Model = require('../shared/Model-Book.json');

const ENGINE = (process.env.SOURCE_ENGINE || 'postgres').toLowerCase();
const API_PORT = parseInt(process.env.API_PORT, 10) || 8086;

const _EngineConfig =
{
	postgres:
	{
		Provider: 'PostgreSQL',
		Module: 'meadow-connection-postgresql',
		SettingsKey: 'PostgreSQL',
		Settings:
		{
			Server: process.env.POSTGRES_HOST || 'postgres',
			Port: parseInt(process.env.POSTGRES_PORT, 10) || 5432,
			User: process.env.POSTGRES_USER || 'postgres',
			Password: process.env.POSTGRES_PASSWORD || '',
			Database: process.env.POSTGRES_DATABASE || 'source4x',
			ConnectionPoolLimit: 5
		}
	},
	mssql:
	{
		Provider: 'MSSQL',
		Module: 'meadow-connection-mssql',
		SettingsKey: 'MSSQL',
		Settings:
		{
			server: process.env.MSSQL_HOST || 'mssql',
			port: parseInt(process.env.MSSQL_PORT, 10) || 1433,
			user: process.env.MSSQL_USER || 'sa',
			password: process.env.MSSQL_PASSWORD || '',
			database: process.env.MSSQL_DATABASE || 'source4x',
			ConnectionPoolLimit: 5,
			options: { trustServerCertificate: true, encrypt: false }
		}
	}
};

const _Engine = _EngineConfig[ENGINE];
if (!_Engine)
{
	console.error(`Unknown SOURCE_ENGINE [${ENGINE}]; expected postgres or mssql.`);
	process.exit(1);
}

/**
 * MSSQL has no CREATE DATABASE IF NOT EXISTS and starts with only the system
 * databases, so the source database is provisioned from master first.  The
 * postgres image creates POSTGRES_DB on its own.
 */
const provisionDatabase = async () =>
{
	if (ENGINE !== 'mssql')
	{
		return;
	}

	const libMSSQL = require('mssql');
	const tmpPool = await libMSSQL.connect(
		{
			server: _Engine.Settings.server,
			port: _Engine.Settings.port,
			user: _Engine.Settings.user,
			password: _Engine.Settings.password,
			database: 'master',
			options: { trustServerCertificate: true, encrypt: false }
		});
	await tmpPool.request().query(`IF DB_ID('${_Engine.Settings.database}') IS NULL CREATE DATABASE [${_Engine.Settings.database}]`);
	await tmpPool.close();
};

const startService = () =>
{
	const tmpSettings =
	{
		Product: 'CloneHarness-Source4x',
		ProductVersion: '1.0.0',
		APIServerPort: API_PORT,
		LogStreams: [ { streamtype: 'console' } ],
		MeadowProvider: _Engine.Provider
	};
	tmpSettings[_Engine.SettingsKey] = _Engine.Settings;

	const tmpFable = new libFable(tmpSettings);

	const tmpProviderServiceName = `Meadow${_Engine.Provider}Provider`;
	tmpFable.serviceManager.addServiceType(tmpProviderServiceName, require(_Engine.Module));
	tmpFable.serviceManager.instantiateServiceProvider(tmpProviderServiceName, {});

	tmpFable[tmpProviderServiceName].connectAsync(
		(pConnectError) =>
		{
			if (pConnectError)
			{
				tmpFable.log.error(`${_Engine.Provider} connection error: ${pConnectError}`);
				return process.exit(1);
			}

			tmpFable[tmpProviderServiceName].createTable(_Model.Tables.Book,
				(pTableError) =>
				{
					if (pTableError)
					{
						tmpFable.log.error(`Could not create the Book table: ${pTableError}`);
						return process.exit(1);
					}

					tmpFable.serviceManager.addServiceType('RetoldDataService', libRetoldDataService);
					const tmpDataService = tmpFable.serviceManager.instantiateServiceProvider('RetoldDataService',
						{
							StorageProvider: _Engine.Provider,
							// Trailing separator required: the data service concatenates path + filename.
							FullMeadowSchemaPath: `${libPath.join(__dirname, '..', 'shared')}/`,
							FullMeadowSchemaFilename: 'Model-Book.json',
							Endpoints: { MeadowEndpoints: true }
						});

					tmpDataService.initializeService(
						(pInitError) =>
						{
							if (pInitError)
							{
								tmpFable.log.error(`Data service initialization error: ${pInitError}`);
								return process.exit(1);
							}
							tmpFable.log.info(`Source 4.x API listening on ${API_PORT} over ${_Engine.Provider}.`);
						});
				});
		});
};

provisionDatabase()
	.then(startService)
	.catch((pError) =>
	{
		console.error(`Source 4.x bootstrap failed: ${pError && pError.message}`);
		process.exit(1);
	});
